import{Engine,esc,el}from'./base.js';
export const tokens=s=>s.match(/[A-Za-z]+(?:'[A-Za-z]+)?|[^A-Za-z]+/g)||[];
export default class TextReader extends Engine{constructor(h,c){super(h,c);this.selected=0;this.seen=new Set;this.words=new Set;let ch=c.chapter;this.positions=(ch.characters||[]).map((p,i)=>({x:Math.max(10,Math.min(490,p.x??i*150)),y:Math.max(20,Math.min(240,p.y??i%2*130))}));h.innerHTML=`<p class="readerNotice">${c.label('Original study companion — not the full copyrighted story. Use the official source link below for the chapter.','मौलिक अध्ययन-सहायक — पूरी मूल कहानी नहीं। मूल अध्याय के लिए नीचे आधिकारिक स्रोत खोलें।')}</p><div class="readerButtons"><button data-read="prev">${c.label('← Previous sentence','← पिछला वाक्य')}</button><button data-read="next">${c.label('Next sentence →','अगला वाक्य →')}</button></div><div class="readerGrid"><div class="passage">${ch.passage.map((s,i)=>`<section class="sentence" data-sentence="${i}"><p lang="en">${tokens(s.en).map(w=>/^[A-Za-z]/.test(w)?`<button class="word ${ch.vocabulary.some(v=>v.word.toLowerCase()===w.toLowerCase())?'difficult':''}" data-word="${esc(w.toLowerCase())}" data-index="${i}">${esc(w)}</button>`:esc(w)).join('')}</p><p class="hi translation">${esc(s.hi)}</p>${ch.kind==='poetry'?`<span class="rhyme rhyme-${s.rhyme||'A'}" title="${esc(c.text(s.device||{en:'No device marked',hi:'कोई अलंकार चिह्नित नहीं'}))}">${esc(s.rhyme||'')}</span><details><summary>${c.label('What does this mean?','इसका अर्थ क्या है?')}</summary><p>${esc(c.text(s.explanation||s))}</p></details>`:''}</section>`).join('')}</div><aside class="wordPanel" aria-live="polite">${c.H({en:'Word Explorer',hi:'शब्द खोज'},3)}<p>${c.dual('Click any English word to see its meaning. Gold words are useful vocabulary.','अर्थ देखने के लिए कोई अंग्रेज़ी शब्द चुनें। सुनहरे शब्द उपयोगी शब्दावली हैं।')}</p></aside></div>${ch.characters?.length?c.H({en:'Character Map',hi:'पात्र मानचित्र'},3)+'<svg class="characterMap" viewBox="0 0 650 330" role="group" aria-label="Character relationships | पात्रों के संबंध"></svg>':''}${ch.plot?.length?c.H({en:'Story So Far',hi:'अब तक की कहानी'},3)+`<div class="plotStrip">${ch.plot.map((p,i)=>`<button data-plot="${i}">${c.H(p.title,4)}</button>`).join('')}</div>`:''}${ch.themeOptions?`<div class="themeChoice">${c.H({en:'Choose the Main Theme',hi:'मुख्य विषय चुनें'},3)}${ch.themeOptions.map((v,i)=>`<button data-theme-choice="${i}">${esc(c.text(v.text))}</button>`).join('')}<p class="themeFeedback" role="status"></p></div>`:''}`;
 this.on(h,'click',e=>{let w=e.target.closest('[data-word]'),r=e.target.closest('[data-read]'),p=e.target.closest('[data-plot]'),th=e.target.closest('[data-theme-choice]');if(w){this.show(+w.dataset.index);this.words.add(w.dataset.word);this.metrics.words=this.words.size;let entry=ch.lexicon[w.dataset.word];h.querySelector('.wordPanel').innerHTML=c.H({en:w.textContent,hi:entry.hi},3)+`<p>${esc(entry.meaning)}</p><p class="hi">${esc(entry.hi)}</p>`;this.emit(`${w.textContent}: ${entry.meaning} | ${entry.hi}`)}if(r)this.show(Math.max(0,Math.min(ch.passage.length-1,this.selected+(r.dataset.read==='next'?1:-1))),true);if(p)this.show(ch.plot[+p.dataset.plot].sentence,true);if(th){let opt=ch.themeOptions[+th.dataset.themeChoice];h.querySelector('.themeFeedback').textContent=c.text(opt.reason);this.metrics.theme=opt.correct;this.emit(c.text(opt.reason))}});this.map=h.querySelector('.characterMap');if(this.map){let drag=null;this.on(this.map,'pointerdown',e=>{let g=e.target.closest('[data-character]');if(!g)return;drag=+g.dataset.character;this.map.setPointerCapture(e.pointerId);e.preventDefault()});this.on(this.map,'pointermove',e=>{if(drag===null)return;let p=this.map.createSVGPoint();p.x=e.clientX;p.y=e.clientY;let q=p.matrixTransform(this.map.getScreenCTM().inverse());this.positions[drag]={x:Math.max(0,Math.min(500,q.x-65)),y:Math.max(0,Math.min(255,q.y-30))};this.metrics.characterMoved=true;this.drawCharacters();this.emit(c.dual('Character positions changed; relationships remain the same.','पात्रों की जगह बदली; संबंध समान हैं।'))});this.on(this.map,'pointerup',()=>drag=null);this.on(this.map,'pointercancel',()=>drag=null);this.on(this.map,'keydown',e=>{let g=e.target.closest('[data-character]');if(!g||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();let i=+g.dataset.character,p=this.positions[i];p.x=Math.max(0,Math.min(500,p.x+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0)));p.y=Math.max(0,Math.min(255,p.y+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0)));this.metrics.characterMoved=true;this.drawCharacters();this.map.querySelector(`[data-character="${i}"]`).focus();this.emit(c.dual('Character moved.','पात्र खिसका।'))});this.drawCharacters()}this.show(0)}
 show(i,scroll=false){this.selected=i;this.seen.add(i);for(let s of this.host.querySelectorAll('.sentence')){let on=+s.dataset.sentence===i;s.classList.toggle('reading',on);s.setAttribute('aria-current',on?'step':'false');if(on&&scroll)s.scrollIntoView({block:'nearest',behavior:'auto'})}this.metrics.sentences=this.seen.size;this.emit(this.ctx.text(this.ctx.chapter.passage[i]))}
 drawCharacters(){let ch=this.ctx.chapter,c=this.ctx;this.map.replaceChildren();let defs=el('defs'),marker=el('marker',{id:'relationshipArrow',viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto-start-reverse'});marker.append(el('path',{d:'M0 0L10 5L0 10Z',fill:'#c9aa68'}));defs.append(marker);this.map.append(defs);for(let r of ch.relationships||[]){let i=ch.characters.findIndex(p=>p.id===r.from),j=ch.characters.findIndex(p=>p.id===r.to);if(i<0||j<0)continue;let a=this.positions[i],b=this.positions[j];this.map.append(el('line',{x1:a.x+70,y1:a.y+33,x2:b.x+70,y2:b.y+33,stroke:'#c9aa68','stroke-width':2,'marker-end':'url(#relationshipArrow)'}));this.map.append(el('text',{x:(a.x+b.x)/2+70,y:(a.y+b.y)/2+25,'text-anchor':'middle'},c.text(r.label)))}ch.characters.forEach((p,i)=>{let pos=this.positions[i],g=el('g',{'data-character':i,tabindex:0,role:'button',transform:`translate(${pos.x} ${pos.y})`,'aria-label':p.name+'. '+c.text(p.description)});g.append(el('rect',{width:140,height:65,rx:10,fill:'#235448',stroke:'#c8d9ca'}));g.append(el('text',{x:10,y:23,'font-weight':'bold'},p.name));g.append(el('text',{x:10,y:46,'font-size':10},c.text(p.description).slice(0,22)+'…'));this.map.append(g)})}
 setLabels(v){this.labels=v;if(this.map)for(let e of this.map.querySelectorAll('text'))e.style.visibility=v?'visible':'hidden'}
 run(){this.schedule(()=>{this.show((this.selected+1)%this.ctx.chapter.passage.length,true);this.run()},4400)}resetView(){this.show(0,true)}}
